(function(){
const E=s=>String(s==null?'':s).replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));
const T=o=>[o.fs&&`font-size:${o.fs}px`,o.fw&&`font-weight:${o.fw}`,o.c&&`color:${o.c}`,o.lh&&`line-height:${o.lh}px`,o.tt&&`text-transform:${o.tt}`,o.ls&&`letter-spacing:${o.ls}`,o.bg&&`background:${o.bg}`].filter(Boolean).join(';');
const A=(href,inner,cls,st)=>`<a href="#"${href?` data-live="${E(href)}"`:''} class="${cls}"${st?` style="${st}"`:''}>${inner}</a>`;
const box=o=>[o.mt&&`margin-top:${o.mt}px`,o.pt&&`padding-top:${o.pt}px`,o.pb&&`padding-bottom:${o.pb}px`,o.bg&&`background:${o.bg}`].filter(Boolean).join(';');
/* carousel arrows: left one at its live inset, right one mirrored; top = % of the image row (or px for rails) */
const arrows=(ar,Wr,top)=>(ar||[]).map(a=>`<i class="hm-ar" style="${a.s==='p'?`left:${a.x}px`:`right:${Wr-a.x-32}px`};top:${top(a)}"></i>`).join('');

function tiles(o,Wr){
  const its=o.items, gap=o.gap||0, n=its.length;
  const sum=its.reduce((s,i)=>s+i.w,0)+(n-1)*gap/Wr*100;
  const fill=!o.wrap&&o.pl===0&&Math.abs(sum-100)<1.5;                    // a row that exactly spans the page
  const cols=o.wrap?Math.max(1,Math.round(100/(its[0].w+gap/Wr*100))):n;
  const W=i=>fill||o.wrap?`calc((100% - ${(cols-1)*gap}px) / ${cols})`:`${i.w}%`;
  const rowH=Wr*its[0].w/100/its[0].ar;
  const cells=its.map((i,k)=>A(i.href,
    `<img src="${E(i.src)}" alt="" style="aspect-ratio:${i.ar}${i.fit==='contain'?';object-fit:contain':''}"${i.round?' class="rd"':''}>`+
    (i.ov||[]).map(v=>`<span class="hm-ov" style="left:${v.x}%;top:${v.y}%;width:${v.w}%;height:${v.h}px;${T(v)}">${E(v.t)}</span>`).join(''),
    'hm-t',`flex:0 0 ${W(i)}${k===0&&o.pl?`;margin-left:${o.pl}px`:''}`)).join('');
  return `<div class="hm-m" style="${box(o)}"><div class="hm-row${o.wrap?' w':''}" style="gap:${o.rg||0}px ${gap}px">${cells}${arrows(o.arrows,Wr,a=>`${((a.y+16-(o.pt||0))/rowH*100).toFixed(2)}%`)}</div></div>`;
}

function card(p,o){
  const s=o.st, sale=!!p.was;
  const price=p.price?`<div class="hm-pr"><span style="${T(sale?s.sale||s.price||{}:s.price||s.sale||{})}">${p.from?'From ':''}${E(p.price)}</span>${sale?`<s style="${T(s.was||{})}">${E(p.was)}</s>`:''}${p.pct&&!/off/i.test(p.pct)?`<span style="${T(s.pct||{})}">${E(p.pct)}</span>`:''}</div>`+(p.pct&&/off/i.test(p.pct)?`<div style="${T(s.pct||{})}">${E(p.pct)}</div>`:''):'';
  return A(p.href,`<img src="${E(p.src)}" alt="" style="width:${p.iw}%;aspect-ratio:${p.ar}${p.fit==='contain'?';object-fit:contain':''}">`+
    `<div class="hm-ci" style="width:${p.iw}%;margin-top:${s.gapTop||12}px">${p.brand?`<div style="${T(s.brand||{})}">${E(p.brand)}</div>`:''}<div class="hm-nm" style="${T(s.name||{})}">${E(p.name)}</div>${price}</div>`,
    'hm-pc',`flex:0 0 ${o.sw}%`);
}

function products(o,Wr){
  const t=o.tab, head=(o.title?`<div class="hm-hd" style="max-width:${t&&t.row?`calc(100% - ${Wr-t.x}px)`:"none"}"><div style="${T(o.ts)};font-weight:${o.ts.fw}">${E(o.title)}</div>${o.sub?`<div style="${T(o.ss)}">${E(o.sub)}</div>`:''}</div>`:'');
  const chips=t?`<div class="hm-tabs${t.on||t.off?'':' u'}" style="gap:${t.gap}px;${t.row?'':`margin-top:${t.mt}px;padding-left:${t.x-(o.title?o.hx:0)}px`}">${o.tabs.map((x,k)=>
    `<span style="height:${t.h}px;font-size:${t.fs}px;font-weight:${t.fw[k?1:0]};color:${(k?t.offc:t.onc)||'inherit'};border-radius:${t.br};${t.on||t.off?`background:${(k?t.off:t.on)||'transparent'};border-color:${k?'#e5e5e5':(t.on||'#e5e5e5')}`:''}${!k&&!(t.on||t.off)?';border-bottom-color:#e5e7eb':''}">${E(x)}</span>`).join('')}</div>`:'';
  const hd=t&&t.row?`<div class="hm-hrow" style="padding-left:${o.hx}px">${head}${chips.replace('style="',`style="right:${t.xr}px;`)}</div>`:`<div style="padding-left:${o.title?o.hx:0}px">${head}${chips}</div>`;
  return `<div class="hm-m hm-p" style="${box(o)}">${hd}<div class="hm-row" style="margin-top:${o.cg}px">${o.items.map((p,k)=>card(p,o).replace('class="hm-pc" style="',`class="hm-pc" style="${k===0&&o.pl?`margin-left:${o.pl}px;`:''}`)).join('')}</div>${arrows(o.arrows,Wr,a=>a.y+'px')}</div>`;
}

const text=o=>`<div class="hm-m hm-tx" style="${box(o)};padding-left:${o.px}px;padding-right:${o.px}px;text-align:${o.ta==='start'?'left':o.ta}">${o.p.map((p,k)=>`<p style="${T(p)}${k?`;margin-top:${o.pg}px`:''}">${E(p.t)}</p>`).join('')}</div>`;

window.renderHome=function(brand,desk){
  const L=(window.HOME_LIVE[brand]||window.HOME_LIVE.debenhams), Wr=desk?1440:390;
  return `<div class="hm">${L.map(x=>x[desk?'d':'m']).filter(Boolean).map(o=>o.t==='products'?products(o,Wr):o.t==='text'?text(o):tiles(o,Wr)).join('')}</div>`;
};

window.HOME_CSS=`
.hm{font-family:var(--font-family-base);color:#000;overflow:hidden}
.hm a{color:inherit;text-decoration:none}
.hm-m{position:relative}
.hm-row{display:flex;flex-wrap:nowrap;position:relative;overflow:hidden}
.hm-row.w{flex-wrap:wrap}
.hm-t{position:relative;display:block;min-width:0}
.hm-t img{display:block;width:100%;height:auto;object-fit:cover}
.hm-t img.rd{border-radius:50%}
.hm-ov{position:absolute;display:flex;align-items:center;justify-content:center;text-align:center;white-space:nowrap;box-sizing:border-box}
.hm-ar{position:absolute;width:32px;height:32px;margin-top:-16px;border-radius:50%;background:rgba(255,255,255,.9);box-shadow:0 0 0 1px rgba(0,0,0,.06);z-index:2;pointer-events:none}
.hm-ar::after{content:'';position:absolute;left:50%;top:50%;width:7px;height:7px;border:solid #000;border-width:0 1.5px 1.5px 0;transform:translate(-65%,-50%) rotate(-45deg)}
.hm-ar[style*="left:"]::after{transform:translate(-35%,-50%) rotate(135deg)}
.hm-p .hm-ar{margin-top:0}
.hm-pc{display:block;min-width:0;box-sizing:border-box}
.hm-pc img{display:block;object-fit:cover;background:#fff}
.hm-ci{display:flex;flex-direction:column;gap:8px}
.hm-nm{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.hm-pr{display:flex;gap:8px;align-items:baseline;flex-wrap:wrap}
.hm-hrow{position:relative}
.hm-hrow .hm-tabs{position:absolute;top:50%;transform:translateY(-50%)}
.hm-tabs{display:flex;flex-wrap:nowrap;overflow:hidden}
.hm-tabs span{display:inline-flex;align-items:center;padding:0 16px;border:1px solid #e5e5e5;white-space:nowrap;flex-shrink:0;box-sizing:border-box}
.hm-tabs.u span{border:0;border-bottom:2px solid transparent;padding:0 16px}
.hm-tx p{margin:0}
`;
})();
